var r=[{title:`Definitioner`,text:`Ett antagonistsupersett varvar motsatta rörelsemönster, till exempel en press följd av en rodd. Ett sammansatt set parar ihop två övningar för samma muskelgrupp. En cirkel kan rotera genom fem stationer innan du vilar och upprepar. EMOM betyder ”varje minut på minuten” och AMRAP betyder ”så många varv eller repetitioner som möjligt” under en fast tid.`},{title:`Varför använda dem`,text:`Att para ihop en press med ett drag låter en muskelgrupp arbeta medan en annan vilar, vilket kan spara tid. Cirklar kan kombinera styrke- och konditionsarbete på liten yta. Många tror att de ger mer styrka eller muskler, men det gör de inte automatiskt. Kvaliteten på det totala arbetet och din återhämtning avgör fortfarande det.`},{title:`Hantera tröttheten`,text:`En tung knäböj parad med en hård marklyft kan försämra båda lyften, särskilt för nybörjare. Para ihop övningar som inte konkurrerar för mycket, och vila tillräckligt länge för att behålla kontrollen. Tekniska lyft och explosiva hopp kräver ofta mer återhämtning än en tidsstyrd cirkel ger. Använd supersetts när du har ont om tid och kombinationen passar ditt mål. Korta inte vilan bara för att nå ett tidsmål, och hoppa över cirklar fulla av hopp eller knepiga rörelser om ditt utrymme, dina bullergränser eller din kropp utesluter dem.`},{title:`Exempel`,text:`Gör tio kontrollerade armhävningar med upphöjda händer, sedan tio stödda rodd och vila sedan 90 sekunder. Upprepa tre gånger. En konditionscirkel kan använda uppsteg, ett lätt bärande och marsch, med planerad vila. Välj ett antal varv som du kan hålla utan att skynda in i dålig teknik.`}];var a=[{label:`NSCA: tidseffektiv träning`,url:`https://www.nsca.com/education/articles/ptq/time-efficient-training`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: säkerhet och grunder i styrketräning`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var n={sections:r,sources:a};export{n as default,r as sections,a as sources};